const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const pt = ee.Geometry.Point([-110.517217, 45.506013]);
    const roi = pt.buffer(3000); // 3 km radius
    const periods = [
      {label: 'Mid-Aug 2012', start: '2012-08-10', end: '2012-08-20'},
      {label: 'Mid-Sep 2012', start: '2012-09-10', end: '2012-09-20'},
    ];
    const scale = 1000; // per requirement to avoid timeouts
    const burnThresh = 0.10; // NBR threshold for likely burn

    // Helpers
    function getInfoAsync(obj) {
      return new Promise((resolve, reject) => {
        obj.getInfo((res, err) => {
          if (err) reject(err);
          else resolve(res);
        });
      });
    }

    function maskL7SR(img) {
      const qa = img.select('QA_PIXEL');
      // Bits: 0 Fill, 1 Dilated, 3 Cloud, 4 Cloud shadow, 5 Snow, 7 Water
      const mask = qa.bitwiseAnd(1 << 0).eq(0)
        .and(qa.bitwiseAnd(1 << 1).eq(0))
        .and(qa.bitwiseAnd(1 << 3).eq(0))
        .and(qa.bitwiseAnd(1 << 4).eq(0))
        .and(qa.bitwiseAnd(1 << 5).eq(0))
        .and(qa.bitwiseAnd(1 << 7).eq(0));
      const scaled = img.select(['SR_B1','SR_B2','SR_B3','SR_B4','SR_B5','SR_B7'])
        .multiply(0.0000275).add(-0.2);
      return scaled.updateMask(mask).copyProperties(img, img.propertyNames());
    }

    function addNBR(img) {
      const nbr = img.normalizedDifference(['SR_B4','SR_B7']).rename('NBR');
      return img.addBands(nbr);
    }

    async function getCollectionWithFallback(startStr, endStr) {
      let start = ee.Date(startStr);
      let end = ee.Date(endStr);
      let col = ee.ImageCollection('LANDSAT/LE07/C02/T1_L2').filterDate(start, end).filterBounds(roi);
      let sizeInit = await getInfoAsync(col.size());
      if (sizeInit === 0) {
        // Widen ±10 days
        start = start.advance(-10, 'day');
        end = end.advance(10, 'day');
        col = ee.ImageCollection('LANDSAT/LE07/C02/T1_L2').filterDate(start, end).filterBounds(roi);
        let sizeWide = await getInfoAsync(col.size());
        if (sizeWide === 0) {
          // Try Tier 2
          let colT2 = ee.ImageCollection('LANDSAT/LE07/C02/T2_L2').filterDate(start, end).filterBounds(roi);
          let sizeT2 = await getInfoAsync(colT2.size());
          const usedStart = await getInfoAsync(start.format('YYYY-MM-dd'));
          const usedEnd = await getInfoAsync(end.format('YYYY-MM-dd'));
          if (sizeT2 === 0) {
            return {col: null, initialSize: 0, usedSize: 0, usedStart, usedEnd, tier: 'None'};
          } else {
            return {col: colT2, initialSize: 0, usedSize: sizeT2, usedStart, usedEnd, tier: 'T2'};
          }
        } else {
          const usedStart = await getInfoAsync(start.format('YYYY-MM-dd'));
          const usedEnd = await getInfoAsync(end.format('YYYY-MM-dd'));
          return {col, initialSize: 0, usedSize: sizeWide, usedStart, usedEnd, tier: 'T1'};
        }
      } else {
        const usedStart = await getInfoAsync(start.format('YYYY-MM-dd'));
        const usedEnd = await getInfoAsync(end.format('YYYY-MM-dd'));
        return {col, initialSize: sizeInit, usedSize: sizeInit, usedStart, usedEnd, tier: 'T1'};
      }
    }

    async function computePeriodStats(label, startStr, endStr) {
      const meta = await getCollectionWithFallback(startStr, endStr);
      if (!meta.col) {
        console.log(label + ' Images: 0');
        return {status: 'C1'};
      }
      console.log(label + ' Images: ' + meta.usedSize + ' (window: ' + meta.usedStart + '..' + meta.usedEnd + ', tier: ' + meta.tier + ')');

      const processed = meta.col.map(maskL7SR).map(addNBR);
      const nbr = processed.median().select('NBR').clip(roi);

      const totalCells = await getInfoAsync(ee.Image.constant(1).reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: roi,
        scale: scale,
        maxPixels: 1e9
      }).get('constant'));
      const validCells = await getInfoAsync(nbr.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: roi,
        scale: scale,
        maxPixels: 1e9
      }).get('NBR'));

      const totalC = totalCells || 0;
      const validC = validCells || 0;
      const maskedPct = totalC > 0 ? (100 * (1 - validC / totalC)) : null;

      if (validC === 0) {
        console.log(label + ' Valid px: 0 / ' + totalC + ' (masked: 100.0%)');
        return {status: 'C2'};
      } else {
        console.log(label + ' Valid px: ' + validC + ' / ' + totalC + ' (masked: ' + maskedPct.toFixed(1) + '%)');
      }

      const burnMask = nbr.lte(burnThresh);
      const areaDict = ee.Image.pixelArea().updateMask(burnMask).reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: roi,
        scale: scale,
        maxPixels: 1e9
      });
      const areaM2 = await getInfoAsync(areaDict.get('area'));
      if (areaM2 === null || isNaN(areaM2)) {
        console.log(label + ' Burn area (ha): NaN');
        return {status: 'C3'};
      }
      const areaHa = areaM2 / 10000.0;
      console.log(label + ' Burn area (ha): ' + areaHa.toFixed(2));
      return {status: 'OK', areaHa};
    }

    // 2. Data Acquisition & Processing
    const s1 = await computePeriodStats(periods[0].label, periods[0].start, periods[0].end);
    if (s1.status !== 'OK') {
      console.log(s1.status);
      return;
    }
    const s2 = await computePeriodStats(periods[1].label, periods[1].start, periods[1].end);
    if (s2.status !== 'OK') {
      console.log(s2.status);
      return;
    }

    // 3. Calculation & Validation
    const area1 = s1.areaHa;
    const area2 = s2.areaHa;
    if (area1 === null || area2 === null || isNaN(area1) || isNaN(area2)) {
      console.log('C3');
      return;
    }

    const delta = area2 - area1;
    console.log('Delta Burn area (ha): ' + delta.toFixed(2));

    // 4. Final Answer
    const tol = 5.0; // tolerance to avoid noise in coarse scale
    if (delta > tol) {
      console.log('A: Yes');
    } else {
      console.log('B: No');
    }
  } catch (err) {
    console.log('Error: ' + (err && err.message ? err.message : String(err)));
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
